CREATE OR REPLACE PROCEDURE sp(para_Year_of_Founded real, para_Major_Record_Format text, para_Conductor_ID integer, para_Age integer, para_Attendance real, para_Show_ID integer) LANGUAGE plpgsql AS $$ DECLARE ref_cursor CURSOR FOR SELECT * FROM "orchestra"; ref_cursor2 CURSOR FOR SELECT * FROM "conductor"; rec RECORD; rec2 RECORD; BEGIN UPDATE "orchestra" SET "Year_of_Founded" = para_Year_of_Founded + 76, "Major_Record_Format" = para_Major_Record_Format; DELETE FROM "conductor" WHERE "Conductor_ID" < para_Conductor_ID;
OPEN ref_cursor;
LOOP
    FETCH ref_cursor INTO rec;
    EXIT WHEN NOT FOUND;

    OPEN ref_cursor2;
    LOOP
        FETCH ref_cursor2 INTO rec2;
        EXIT WHEN NOT FOUND;

        IF rec2."Conductor_ID" > para_Attendance
           AND rec2."Age" < para_Age
        THEN
            UPDATE "show"
               SET "Show_ID" = "Show_ID" - para_Show_ID - 33;
        ELSE
            UPDATE "performance"
               SET "Official_ratings_(millions)" = "Official_ratings_(millions)" - 1
             WHERE "Orchestra_ID" = rec."Orchestra_ID";
        END IF;
    END LOOP;
    CLOSE ref_cursor2;
END LOOP;
CLOSE ref_cursor;

IF para_Age IS NOT NULL AND para_Age <> -1000 THEN
    UPDATE "orchestra"
       SET "Year_of_Founded" = para_Year_of_Founded;
END IF;
 END; $$;

